import React from "react";
import { useState } from "react";
import "../css/SignIn.css";
import googleIcon from "../assets/google-brands-solid.svg";
import twitterIcon from "../assets/x-twitter-brands-solid.svg";
import { Link } from "react-router-dom";
import { useSignUp } from '@clerk/clerk-react';


const SignIn = () => {
    const { signUp, setSession, isLoaded, error } = useSignUp();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [step, setStep] = useState('signUp'); // for multi-step flow like email verification

  if (!isLoaded) return null; // wait for Clerk to load

  const handleSignUp = async (e) => {
    e.preventDefault();
    try {
      await signUp.create({ emailAddress: email, password });
      await signUp.prepareEmailAddressVerification({ strategy: 'email_code' });
      setStep('verify'); // Move to verification step UI
    } catch (err) {
      // handle error (show error.message)
    }
  }
  return (
    <div className="container">
      <h1 className="header"> Register </h1>
      <p className="subtext">Already have an account ? <Link to="/login">Log In</Link></p>
       <form>
        <label htmlFor="username">Username</label>
        <input
          type="text"
          id="username"
          name="username"
          placeholder="john"
        />
        <label htmlFor="email">Email</label>
        <input
          type="email"
          id="email"
          name="email"
          placeholder="m@example.com"
        />
        <label htmlFor="password">Password</label>
        <input type="password" id="password" name="password" />
        <button type="submit" className="submit">
          <span>Sign Up</span>
        </button>
      </form>
     
      <div className="divider">
        <span>OR</span>
      </div>
       <div className="button-group">
        <button className="button">
          <img src={twitterIcon} alt="Twitter Icon" width={20} height={20} />{" "}
          Twitter
        </button>
        <button className="button">
          <img src={googleIcon} alt="Google Icon" width={20} height={20} />{" "}
          Google
        </button>
      </div>
     
    </div>
  );
};

export default SignIn;
